import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';

registerWebComponents([VlButtonComponent]);

document.querySelector('vl-button').addEventListener('vl-click', () => {
    console.log('vl-click');
});

components-atom-button--button-toggle.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';

registerWebComponents([VlButtonComponent]);

// vl-toggle volgt op een wijziging van on, door een klik of door on te zetten; de nieuwe toestand staat in
// event.detail.on.
document.querySelector('vl-button[toggle]').addEventListener('vl-toggle', (event) => {
    console.log(event.detail.on ? 'aan' : 'uit');
});
